SourceCode.Declaration:
/// <summary>
/// listTransferOrders / listPickedSerials request. Days limits how far back serials go (default 30); Search filters serials by item or serial.
/// </summary>
[DataContractAttribute]
class HSMobileOpsTransferListRequest
{
    DataAreaId dataAreaId;
    str        warehouseId;
    int        days;
    str        search;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('WarehouseId')]
public str parmWarehouseId(str _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('Days')]
public int parmDays(int _value = days)
{
    days = _value;
    return days;
}

[DataMemberAttribute('Search')]
public str parmSearch(str _value = search)
{
    search = _value;
    return search;
}
